//! Route table and router assembly.
//!
//! [`ROUTES`] is the single source of truth for what coolify-rs implements:
//! the router applies each entry's abilities, and
//! `tests/route_inventory.rs` checks every entry against the upstream route
//! inventory generated by `coolify-port` (method, URI, group, abilities).

pub mod applications;
pub mod cloud_providers;
pub mod cloud_tokens;
pub mod databases;
pub mod destinations;
pub mod misc;
pub mod private_keys;
pub mod projects;
pub mod server_proxy;
pub mod server_settings;
